static int fimc_is_load_setfile ( struct fimc_is * is , char * file_name ) { const struct firmware * fw ; void * buf ; int ret ; ret = request_firmware ( & fw , file_name , & is -> pdev -> dev ) ; buf = is -> memory . vaddr + is -> setfile . base ; memcpy ( buf , fw -> data , fw -> size ) ; fimc_is_mem_barrier ( ) ; is -> setfile . size = fw -> size ; pr_debug ( "mem vaddr: %p, setfile buf: %p\n" , is -> memory . vaddr , buf ) ; memcpy ( is -> fw . setfile_info , fw -> data + fw -> size - FIMC_IS_SETFILE_INFO_LEN , FIMC_IS_SETFILE_INFO_LEN - 1 ) ; is -> fw . setfile_info [ FIMC_IS_SETFILE_INFO_LEN - 1 ] = '\0' ; is -> setfile . state = 1 ; pr_debug ( "FIMC-IS setfile loaded: base: %#x, size: %zu B\n" , is -> setfile . base , fw -> size ) ; release_firmware ( fw ) ; return ret ; } 